(defn- parse [s]
  (if (str/blank? s) {}
      (into {} (map (fn [kv] (let [i (str/index-of kv "=")] [(subs kv 0 i) (subs kv (inc i))]))
                    (str/split s #"\|")))))
(def ^:private parsed (atom {}))
(defn- table* [id]
  (or (get @parsed id)
      (let [spec (get raw id)
            t (into {:separator (:separator spec)}
                    (for [k [:languages :countries :scripts :variants]] [k (parse (get spec k ""))]))
            ;; ROOT holds only what differs from en; a name it lacks is its code
            t (if (= id "")
                (merge-with (fn [a b] (if (map? a) (into {} (remove (fn [[k v]] (= k v)) (merge a b))) b)) (table* "en") t)
                t)]
        (swap! parsed assoc id t)
        t)))
(defn- display-id
  "The table a display locale id reads: itself, its language, else ROOT."
  [id]
  (cond (contains? raw id) id
        (contains? raw (first (str/split id #"-"))) (first (str/split id #"-"))
        :else ""))
(defn names [id] (table* (display-id id)))
